  auto PAYMENT_CHAIN__ = PAYMENT_CHAIN ? _fbb.CreateString(PAYMENT_CHAIN) : 0;
  auto DELIVERY_TOPIC__ = DELIVERY_TOPIC ? _fbb.CreateString(DELIVERY_TOPIC) : 0;
